## @WebMvcTest Setup

```java
@WebMvcTest(OrderController.class)  // Only load OrderController and its dependencies
@AutoConfigureMockMvc
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;  // For serializing request bodies

    @MockBean
    private OrderService orderService;

    @MockBean
    private OrderMapper orderMapper;

    // GET — successful response
    @Test
    void shouldReturnOrderWhenFound() throws Exception {
        OrderResponse response = OrderResponse.builder()
            .id(42L).status("PENDING").total(new BigDecimal("99.99")).build();

        when(orderService.findById(42L)).thenReturn(buildOrder(42L));
        when(orderMapper.toResponse(any())).thenReturn(response);

        mockMvc.perform(get("/api/orders/42")
                .accept(MediaType.APPLICATION_JSON))
            .andDo(print())  // Print request/response to stdout
            .andExpect(status().isOk())
            .andExpect(content().contentType(MediaType.APPLICATION_JSON))
            .andExpect(jsonPath("$.id").value(42))
            .andExpect(jsonPath("$.status").value("PENDING"))
            .andExpect(jsonPath("$.total").value(99.99));
    }

    // GET — not found
    @Test
    void shouldReturn404WhenOrderNotFound() throws Exception {
        when(orderService.findById(99L)).thenThrow(new OrderNotFoundException(99L));

        mockMvc.perform(get("/api/orders/99"))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.errorCode").value("ORDER_NOT_FOUND"));
    }

    // POST — valid request
    @Test
    void shouldCreateOrderAndReturn201() throws Exception {
        CreateOrderRequest request = buildValidRequest();
        Order created = buildOrder(1L);
        OrderResponse response = buildOrderResponse(1L);

        when(orderService.createOrder(any(), any())).thenReturn(created);
        when(orderMapper.toResponse(created)).thenReturn(response);

        mockMvc.perform(post("/api/orders")
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(request))
                .with(user("testuser").roles("USER")))  // Authenticated user
            .andExpect(status().isCreated())
            .andExpect(header().string("Location", containsString("/api/orders/1")))
            .andExpect(jsonPath("$.id").value(1));
    }

    // POST — validation failure
    @Test
    void shouldReturn400WhenRequestInvalid() throws Exception {
        CreateOrderRequest invalidRequest = new CreateOrderRequest();  // Missing required fields

        mockMvc.perform(post("/api/orders")
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(invalidRequest)))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.fieldErrors").isArray())
            .andExpect(jsonPath("$.fieldErrors[*].field",
                hasItems("userId", "items")));
    }

    // DELETE — successful
    @Test
    void shouldReturn204WhenDeleted() throws Exception {
        doNothing().when(orderService).delete(42L);

        mockMvc.perform(delete("/api/orders/42")
                .with(user("admin").roles("ADMIN")))
            .andExpect(status().isNoContent());
    }
}
```

## Security Testing with @WithMockUser

```java
@WebMvcTest(OrderController.class)
@Import(SecurityConfig.class)  // Include security config if testing auth
class OrderSecurityTest {

    @Autowired private MockMvc mockMvc;
    @MockBean private OrderService orderService;
    @MockBean private UserDetailsService userDetailsService;

    @Test
    @WithAnonymousUser
    void shouldReturn401WhenNotAuthenticated() throws Exception {
        mockMvc.perform(get("/api/orders"))
            .andExpect(status().isUnauthorized());
    }

    @Test
    @WithMockUser(roles = "USER")
    void shouldReturn200WhenAuthenticated() throws Exception {
        when(orderService.findAll(any(), any())).thenReturn(Page.empty());
        mockMvc.perform(get("/api/orders"))
            .andExpect(status().isOk());
    }

    @Test
    @WithMockUser(roles = "USER")  // No ADMIN role
    void shouldReturn403WhenNotAdmin() throws Exception {
        mockMvc.perform(delete("/api/orders/1"))
            .andExpect(status().isForbidden());
    }

    @Test
    @WithMockUser(roles = "ADMIN")
    void shouldAllowAdminToDelete() throws Exception {
        doNothing().when(orderService).delete(1L);
        mockMvc.perform(delete("/api/orders/1"))
            .andExpect(status().isNoContent());
    }
}
```

