    .andReturn();
String body = result.getResponse().getContentAsString();
OrderResponse response = objectMapper.readValue(body, OrderResponse.class);
assertThat(response.getId()).isEqualTo(1L);
```

## Production Reality

`@WebMvcTest` tests run in 1-3 seconds per test class (context cached within class). They're the right tool for verifying HTTP contracts: correct status codes, correct Content-Type, request body parsing, response serialization, and security rules. Don't duplicate unit test assertions here — trust the service unit test. Focus on "does the HTTP layer work correctly?"

## @DataJpaTest Setup

```java
@DataJpaTest
class OrderRepositoryTest {

    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private TestEntityManager em;  // For setting up test data

    @Test
    void shouldFindOrdersByStatus() {
        // ARRANGE: Create test data via EntityManager
        User user = em.persist(User.builder().email("test@example.com").build());
        em.persist(Order.builder().user(user).status(PENDING).total(BigDecimal.TEN).build());
        em.persist(Order.builder().user(user).status(SHIPPED).total(BigDecimal.ONE).build());
        em.persist(Order.builder().user(user).status(PENDING).total(BigDecimal.TEN).build());
        em.flush();  // Write to H2 in-memory DB

        // ACT: Call repository method
        List<Order> pendingOrders = orderRepository.findByStatus(PENDING);

        // ASSERT:
        assertThat(pendingOrders).hasSize(2);
        assertThat(pendingOrders).extracting(Order::getStatus)
            .containsOnly(PENDING);
    }

    @Test
    void shouldReturnOrdersSortedByCreatedAt() {
        User user = em.persist(User.builder().email("a@b.com").build());
        Order older = em.persist(Order.builder().user(user)
            .createdAt(LocalDateTime.now().minusDays(2)).build());
        Order newer = em.persist(Order.builder().user(user)
            .createdAt(LocalDateTime.now()).build());
        em.flush();

        List<Order> orders = orderRepository.findAllByOrderByCreatedAtDesc();

        assertThat(orders.get(0).getId()).isEqualTo(newer.getId());
        assertThat(orders.get(1).getId()).isEqualTo(older.getId());
    }

    @Test
    void shouldCountByStatusGrouped() {
        User user = em.persist(User.builder().email("x@y.com").build());
        em.persist(Order.builder().user(user).status(PENDING).build());
        em.persist(Order.builder().user(user).status(PENDING).build());
        em.persist(Order.builder().user(user).status(SHIPPED).build());
        em.flush();

        // Test custom @Query:
        // @Query("SELECT o.status, COUNT(o) FROM Order o GROUP BY o.status")
        List<Object[]> counts = orderRepository.countByStatusGrouped();

        Map<OrderStatus, Long> countMap = counts.stream()
            .collect(Collectors.toMap(
                row -> (OrderStatus) row[0],
                row -> (Long) row[1]
            ));

        assertThat(countMap.get(PENDING)).isEqualTo(2L);
        assertThat(countMap.get(SHIPPED)).isEqualTo(1L);
    }
}
```

## Real Database with Testcontainers

```java
// For PostgreSQL-specific queries that don't work in H2:
@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@Testcontainers
class OrderRepositoryPostgresTest {

    @Container
    static PostgreSQLContainer<?> postgres =
        new PostgreSQLContainer<>("postgres:15")
            .withDatabaseName("testdb")
            .withUsername("test")
            .withPassword("test");

    @DynamicPropertySource
    static void configureProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
    }

    @Test
    void shouldUsePostgresSpecificQuery() {
        // Test PostgreSQL-specific native queries (window functions, etc.)
    }
}
```

## What to Test vs Not Test

```java
// TEST: Your custom @Query methods
@Query("SELECT o FROM Order o WHERE o.total > :minTotal AND o.status = :status")
List<Order> findHighValueByStatus(@Param("minTotal") BigDecimal min,
                                   @Param("status") OrderStatus status);

// TEST: Custom derived query with complex criteria:
List<Order> findByUserIdAndStatusInAndCreatedAtAfter(
    Long userId, List<OrderStatus> statuses, LocalDateTime since);

// TEST: Pagination works correctly with your custom query:
Page<Order> findByStatusOrderByCreatedAtDesc(OrderStatus status, Pageable pageable);

// DON'T TEST (framework-provided):
Optional<Order> findById(Long id);        // Spring Data CRUD
List<Order> findAll();                     // Spring Data CRUD
Order save(Order order);                  // Spring Data CRUD
exists(Long id);                          // Spring Data CRUD
void deleteById(Long id);                 // Spring Data CRUD
```

## Production Reality

H2 is acceptable for basic JPQL queries. Switch to Testcontainers for any test that exercises native SQL, database-specific functions, constraint violations (FK, unique), or trigger behavior. The overhead of Testcontainers is ~5-10 seconds per test class (PostgreSQL startup), which is worth it for high-fidelity testing of database-critical code. Configure the Testcontainer at the class level — reuse across tests in the same class.
